// ===== CONFIG =====
const BUSINESS = 'Your Business';
const YOUR_INBOX = 'you@youremail.com';
// ==================

const i = $input.first().json; const b = i.body || i;
const name = String(b.name || b.Name || 'there').trim();
const email = String(b.email || b.Email || '').trim();
const message = String(b.message || b.Message || b.msg || '').trim();
const hp = String(b.website || b.url || '').trim(); // honeypot

// bot check: honeypot filled OR no real content
if (hp || (!email && !message)) {
  return [{ json: { skip: true, ownerTo: YOUR_INBOX, ownerSubject: '', ownerBody: '', replyTo: '', replySubject: '', replyBody: '', sendReply: false } }];
}

const autoReply = 'Hi ' + name + ',\n\nThanks for reaching out to ' + BUSINESS + ' - we got your message and will get back to you shortly.\n\nFor reference, here is what you sent:\n"' + (message || '(no message)') + '"\n\nTalk soon,\n' + BUSINESS;
const ownerBody = 'New contact form submission\n\nName: ' + name + '\nEmail: ' + (email || '(none)') + '\n\nMessage:\n' + (message || '(none)');

return [{ json: {
  skip: false,
  ownerTo: YOUR_INBOX,
  ownerSubject: '[' + BUSINESS + '] New lead: ' + name,
  ownerBody: ownerBody,
  replyTo: email,
  replySubject: 'Thanks for reaching out to ' + BUSINESS,
  replyBody: autoReply,
  sendReply: !!email
} }];
